import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import api from "../../api/axios";


const TicketDetail = () => {
  const { id } = useParams();
  const [ticket, setTicket] = useState(null);
  const isAdmin = localStorage.getItem("is_staff") === "true";

  useEffect(() => {
    api.get(`tickets/${id}/`)
      .then(res => setTicket(res.data))
      .catch(console.error);
  }, [id]);

  const updateStatus = (status) => {
    api.patch(`tickets/${id}/`, { status })
      .then(res => setTicket(res.data));
  };

  if (!ticket) return <p>Loading...</p>;

  return (
    <div className="container mt-4">
      <h3>{ticket.title}</h3>

      <p>{ticket.description}</p>
      <p>Priority: <b>{ticket.priority}</b></p>
      <p>Status: <b>{ticket.status}</b></p>

      {ticket.attachment && (
        <a href={ticket.attachment} target="_blank" rel="noreferrer">
          Download Attachment
        </a>
      )}

      {isAdmin && (
        <>
          <hr />
          <h5>Confidential Notes</h5>
          <p>{ticket.confidential_notes}</p>

          <button onClick={() => updateStatus("RESOLVED")}
            className="btn btn-success">
            Mark Resolved
          </button>
        </>
      )}

      <hr />
      <h5>Audit Log</h5>
      {ticket.audit_logs?.map(log => (
        <p key={log.id}>{log.message}</p>
      ))}
    </div>
  );
};

export default TicketDetail;
